std::string s = "Value: 42.99, Error: N/A";
size_t start = s.find_first_of("0123456789.");
double result = 0.0;

if (start != std::string::npos) {
    // Determine the end of the numeric substring
    size_t end = s.find_first_of(", ", start);
    std::string num_str = s.substr(start, end - start);

    try {
        // Safe conversion to double
        result = std::stod(num_str);
    } catch (const std::invalid_argument& e) {
        // Substring was found but not convertible (e.g., "...")
        result = 0.0;
    } catch (const std::out_of_range& e) {
        // Number exceeds double limits
        result = 0.0;
    }
}
